import {transactions} from './data.js';
import {calculate,validateDecision,addDecision,restoreState,emptyState,currentStatus,STATUS} from './domain.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:0}).format(n);
const stats=calculate(transactions);
const storageKey='signal-aml-demo-v1';
let state=emptyState(),storageOK=true;
try{state=restoreState(localStorage.getItem(storageKey));}catch{storageOK=false;}
let view='queue',tab='overview',direction='All',txSearch='',txSort='asc',keyOnly=false,queueSearch='',queueFilter='All',chartDay=0,saved=false;
let draft=newDraft();
function newDraft(){return {outcome:'escalate',rationale:'',requestItem:'',owner:'Seyoung Yoo (demo)',dueDate:'2026-11-18'};}
const app=$('#app-content');
function toast(message){const node=$('#toast');node.textContent=message;node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,4500);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Decision is available for this session. Browser storage is unavailable; export the log to keep a copy.');}}
function badge(status){return `<span class="status ${status==='Escalated'?'escalated':status==='Information requested'?'requested':status==='Closed'?'closed':''}">${esc(status)}</span>`;}
function timestamp(iso){return new Intl.DateTimeFormat('en-CA',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Toronto',timeZoneName:'short'}).format(new Date(iso));}
function show(next,focus=true){view=next;saved=false;render();if(focus)app.focus({preventScroll:true});}
function render(){
  document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  $('#breadcrumb').textContent=`Financial crime / ${view==='queue'?'Alert queue':view==='history'?'Decision log':'ALT-1042'}`;
  if(view==='queue')renderQueue();else if(view==='history')renderHistory();else renderCase();
}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='case')tab='overview';show(b.dataset.view);}));
function renderQueue(){
  const status=currentStatus(state),closed=status==='Closed';
  app.innerHTML=`<div class="app-heading"><div><p class="eyebrow">YOUR WORKSPACE</p><h2>Alert queue</h2><p>Start with the pattern. Decide with the evidence.</p></div><span class="pill">DEMO · 1 CASE</span></div><div class="queue-stats"><div><strong>1</strong><span>Synthetic alert</span></div><div><strong>${closed?0:1}</strong><span>Open for review</span></div><div><strong>${closed?1:0}</strong><span>Closed with rationale</span></div></div><div class="filter-bar"><label class="field-inline">Search <input id="queue-search" type="search" placeholder="Alert or customer" value="${esc(queueSearch)}"></label><label class="field-inline">Status <select id="queue-status">${['All','New','Escalated','Information requested','Closed'].map(s=>`<option${s===queueFilter?' selected':''}>${s}</option>`).join('')}</select></label></div><div id="queue-results"></div><div class="queue-note"><strong>Try a complete review.</strong><br>Open ALT-1042 to inspect customer context and transaction timing. Save a decision, then return here to see the status change.</div>${!storageOK?'<p class="small">Browser storage is unavailable. Decisions will only last for this session.</p>':''}`;
  const draw=()=>{
    const match=(queueFilter==='All'||queueFilter===status)&&'alt-1042 juniper design c-0184'.includes(queueSearch.toLowerCase().trim());
    $('#queue-results').innerHTML=match?`<div class="table-wrap" role="region" aria-label="Alert queue table" tabindex="0"><table><caption class="sr-only">Synthetic alert queue</caption><thead><tr><th>Alert / customer</th><th>Trigger</th><th>Priority</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td><strong>ALT-1042</strong><small>Juniper Design · C-0184</small></td><td>Incoming → rapid outgoing<small>7–13 Nov 2026 · CAD</small></td><td><span class="status high">High</span></td><td>${badge(status)}</td><td><button id="open-alert" class="table-link">Review alert →</button></td></tr></tbody></table></div>`:'<div class="panel empty-state"><h3>No matching alerts</h3><p>Try another status or clear your search. This demo contains one fictional alert.</p><button id="clear-queue" class="button secondary">Clear filters</button></div>';
    $('#open-alert')?.addEventListener('click',()=>{tab='overview';show('case');});
    $('#clear-queue')?.addEventListener('click',()=>{queueSearch='';queueFilter='All';renderQueue();});
  };
  $('#queue-search').addEventListener('input',e=>{queueSearch=e.target.value;draw();});
  $('#queue-status').addEventListener('change',e=>{queueFilter=e.target.value;draw();});draw();
}
function renderCase(){
  app.innerHTML=`<button class="back-link" id="back-queue">← Back to alert queue</button>${saved?'<div class="saved-banner" role="status">Decision recorded. The queue and decision log have been updated in this browser.</div>':''}<div class="app-heading"><div><h2>ALT-1042</h2><p>C-0184 · Juniper Design · Small business · CAD</p><div class="case-meta"><span class="status high">High priority</span>${badge(currentStatus(state))}<span>Assigned to you · Created 14 Nov 2026, 09:12 ET</span></div></div><button class="button primary" id="record-decision">Record decision</button></div><div class="tabs" role="tablist" aria-label="Alert detail"><button id="tab-overview" role="tab" aria-selected="${tab==='overview'}" aria-controls="case-panel" tabindex="${tab==='overview'?0:-1}" data-tab="overview">Overview</button><button id="tab-transactions" role="tab" aria-selected="${tab==='transactions'}" aria-controls="case-panel" tabindex="${tab==='transactions'?0:-1}" data-tab="transactions">Transactions</button><button id="tab-explanation" role="tab" aria-selected="${tab==='explanation'}" aria-controls="case-panel" tabindex="${tab==='explanation'?0:-1}" data-tab="explanation">Why this alert?</button><button id="tab-decision" role="tab" aria-selected="${tab==='decision'}" aria-controls="case-panel" tabindex="${tab==='decision'?0:-1}" data-tab="decision">Decision</button></div><div id="case-panel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="0"></div>`;
  $('#back-queue').onclick=()=>show('queue');$('#record-decision').onclick=()=>{tab='decision';renderCase();$('#rationale')?.focus({preventScroll:true});};
  const tabs=[...document.querySelectorAll('[data-tab]')];
  tabs.forEach((b,i)=>{b.onclick=()=>{tab=b.dataset.tab;renderCase();$(`#tab-${tab}`).focus({preventScroll:true});};b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tab=tabs[next].dataset.tab;renderCase();$(`#tab-${tab}`).focus({preventScroll:true});}};});
  if(tab==='overview')renderOverview();else if(tab==='transactions')renderTransactions();else if(tab==='explanation')renderExplanation();else renderDecision();
}
function evidencePanel(){return state.evidence?`<div class="notice success"><strong>Hypothetical evidence loaded</strong><br>Example invoices match the 14 incoming transfers; a fictional supplier schedule explains both outgoing payments. Assume the reviewer verified these documents for this scenario only.</div>`:`<div class="notice warning"><strong>What is still unknown?</strong><br>The transfer purpose, invoices and relationships between counterparties have not been verified. This pattern alone cannot establish wrongdoing.</div>`;}
function renderOverview(){
  $('#case-panel').innerHTML=`<div class="case-grid"><div><section class="panel"><span class="pill">REVIEW CONTEXT</span><p class="lead-pattern">Several incoming transfers followed by two larger outgoing transfers.</p></section>${evidencePanel()}<div class="kpis"><div><strong>$${money(stats.incoming)}</strong><p>Incoming · 7 days</p><small>14 transfers · 8 counterparties</small></div><div><strong>$${money(stats.outgoing)}</strong><p>Outgoing after last inflow</p><small>2 transfers · within 90 min</small></div><div><strong>${stats.ratio.toFixed(1)}× baseline</strong><p>Weekly incoming value</p><small>Compared with CAD 7,600</small></div></div><section class="panel"><h3>Incoming transfer value</h3><p>CAD · 7–13 Nov 2026 · Select a day to inspect its total.</p><div class="chart">${stats.daily.map((d,i)=>`<button aria-label="${7+i} November: CAD ${money(d.amount)}" aria-pressed="${chartDay===i}" data-day="${i}"><span>${money(d.amount)}</span><span class="bar" style="height:${d.amount/35}px"></span><span>${7+i} Nov</span></button>`).join('')}</div><div class="chart-detail" id="chart-detail" role="status"></div><p class="small">Assumed weekly baseline: CAD 7,600. Daily bars sum to CAD 19,600.</p></section></div><aside><section class="panel"><h3>Customer context</h3><p><span class="pill">Fictional profile</span></p><h3 style="font-size:17px;margin-top:15px">Juniper Design</h3><p>Design services · Canada</p><dl class="profile-list"><dt>Account opened</dt><dd>18 Apr 2025</dd><dt>Expected monthly activity</dt><dd>CAD 25k–40k</dd><dt>Profile verification</dt><dd>Scenario assumption</dd></dl></section><section class="panel"><div class="priority"><h3>Review order</h3><strong>High</strong></div><p>Illustrative review order. Check the evidence and missing context before choosing a next step. No model is connected.</p></section><section class="panel"><h3>Activity log</h3><ul class="activity-list"><li>14 Nov, 09:12 · Alert generated<span>Fictional rule RM-02 triggered</span></li><li>14 Nov, 09:14 · Assigned to you<span>Scenario review begins</span></li>${state.records.slice(-2).map(r=>`<li>${esc(timestamp(r.at))} · ${esc(STATUS[r.outcome])}<span>${esc(r.id)} · Browser demo decision</span></li>`).join('')}</ul></section></aside></div>`;
  const detail=()=>$('#chart-detail').textContent=`${7+chartDay} Nov: CAD ${money(stats.daily[chartDay].amount)} from 2 incoming transfers.`;
  document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{chartDay=Number(b.dataset.day);document.querySelectorAll('[data-day]').forEach(d=>d.setAttribute('aria-pressed',Number(d.dataset.day)===chartDay));detail();});detail();
}
function renderTransactions(){
  $('#case-panel').innerHTML=`<section class="panel"><h3>Transaction timeline</h3><p>The final incoming transfer is at 19:30 ET on 13 Nov. The outgoing transfers follow at 20:14 and 20:49 ET.</p><div class="sequence"><div><strong>19:30 · +$1,300</strong><span>Final incoming transfer</span></div><div><strong>20:14 · −$10,200</strong><span>44 minutes later</span></div><div><strong>20:49 · −$7,600</strong><span>79 minutes later</span></div></div></section><div class="filter-bar"><label class="field-inline">Direction <select id="tx-direction">${['All','Incoming','Outgoing'].map(s=>`<option${direction===s?' selected':''}>${s}</option>`).join('')}</select></label><label class="field-inline">Search <input id="tx-search" type="search" placeholder="ID or counterparty" value="${esc(txSearch)}"></label><label class="field-inline">Order <select id="tx-sort"><option value="asc"${txSort==='asc'?' selected':''}>Oldest first</option><option value="desc"${txSort==='desc'?' selected':''}>Newest first</option></select></label><label class="field-inline"><input type="checkbox" id="key-only"${keyOnly?' checked':''}>Key sequence only</label></div><div class="transaction-summary"><span id="tx-count" role="status"></span><button id="export-csv" class="quiet">Export visible CSV ↓</button></div><div id="tx-results"></div><p class="small" style="margin-top:12px">All times are Eastern Standard Time (UTC−05:00). Amounts are CAD. No source challenge transactions are included.</p>`;
  const filtered=()=>transactions.filter(t=>(direction==='All'||t.direction===direction)&&(!keyOnly||Number(t.id.slice(3))>=2014)&&`${t.id} ${t.counterparty}`.toLowerCase().includes(txSearch.toLowerCase().trim())).sort((a,b)=>txSort==='asc'?a.id.localeCompare(b.id):b.id.localeCompare(a.id));
  const draw=()=>{const rows=filtered();$('#tx-count').textContent=`${rows.length} of 16 synthetic transactions · Visible total CAD ${money(rows.reduce((s,t)=>s+t.amount,0))} (unsigned)`;$('#tx-results').innerHTML=rows.length?`<div class="table-wrap" role="region" aria-label="Transaction timeline table" tabindex="0"><table><caption class="sr-only">Synthetic transaction timeline</caption><thead><tr><th>Date / time (ET)</th><th>Transaction / counterparty</th><th>Direction</th><th class="amount">Amount (CAD)</th><th>Context</th></tr></thead><tbody>${rows.map(t=>`<tr class="${t.direction==='Outgoing'?'outgoing-row':''}"><td>${t.date.slice(8)} Nov 2026<small>${t.time}</small></td><td><strong>${esc(t.id)}</strong><small>${esc(t.counterparty)}</small></td><td><span class="${t.direction==='Outgoing'?'flow-out':'flow-in'}">${t.direction==='Outgoing'?'↗ Outgoing':'↙ Incoming'}</span></td><td class="amount">${money(t.amount)}</td><td>${t.id==='TX-2014'?'Final inflow':t.id==='TX-2015'?'44 min after last inflow':t.id==='TX-2016'?'79 min after last inflow':'Review window'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel empty-state">No transactions match these filters.</div>';};
  $('#tx-direction').onchange=e=>{direction=e.target.value;draw();};$('#tx-search').oninput=e=>{txSearch=e.target.value;draw();};$('#tx-sort').onchange=e=>{txSort=e.target.value;draw();};$('#key-only').onchange=e=>{keyOnly=e.target.checked;draw();};$('#export-csv').onclick=()=>download('signal-visible-transactions.csv',toCSV(filtered()),'text/csv');draw();
}
function renderExplanation(){
  $('#case-panel').innerHTML=`<section class="panel"><span class="pill">FICTIONAL RULE RM-02</span><h3 style="font-size:18px;margin-top:13px">Higher incoming value, followed by rapid outgoing transfers</h3><p>This scenario rule triggers when incoming value exceeds twice the assumed weekly baseline and at least 80% of that value leaves within 90 minutes of the final incoming transfer.</p><ol class="rule-list"><li><span class="rule-check">✓</span><div>Weekly incoming value exceeds 2× baseline<small>CAD 19,600 ÷ CAD 7,600 = 2.5789. The CAD 7,600 baseline is authored for this scenario.</small></div><span class="rule-result">2.58× &gt; 2×</span></li><li><span class="rule-check">✓</span><div>At least 80% of incoming value is sent out<small>CAD 17,800 ÷ CAD 19,600 = 90.8163%. This compares totals; it does not prove these are the same funds.</small></div><span class="rule-result">90.8% ≥ 80%</span></li><li><span class="rule-check">✓</span><div>Both outflows occur within 90 minutes<small>19:30 → 20:14 = 44 minutes. 19:30 → 20:49 = 79 minutes, on 13 Nov 2026.</small></div><span class="rule-result">44 & 79 min</span></li></ol></section><div class="case-grid"><section class="panel"><h3>What supports a closer look?</h3><p>A higher weekly incoming total and two rapid, relatively large outgoing transfers. The sequence can justify asking for purpose and supporting documents.</p><button class="button secondary" id="inspect-sequence">Inspect the transactions →</button></section><section class="panel"><h3>What could explain the pattern?</h3><p>Invoice collections followed by supplier payments could be consistent with a small business. That explanation remains unverified in the initial scenario.</p></section></div><div style="margin-top:15px">${evidencePanel()}</div><p class="small">This is an illustrative rule, not a bank policy, regulatory threshold, machine-learning output or determination of suspicious activity.</p>`;
  $('#inspect-sequence').onclick=()=>{tab='transactions';keyOnly=true;direction='All';txSearch='';renderCase();$('#case-panel').focus({preventScroll:true});};
}
function renderDecision(errors=[]){
  const panel=$('#case-panel');
  panel.innerHTML=`<div class="decision-layout"><section class="panel"><h3>Record a decision</h3><p>Explain what the evidence supports and what should happen next. Saving updates this browser demo only.</p><form id="decision-form" class="decision-form" novalidate><fieldset><legend>Next step</legend>${[['escalate','Escalate for investigation','The pattern needs a deeper review.'],['request','Request information','Specify missing evidence and a follow-up date.'],['close','Close with rationale','Requires the hypothetical supporting evidence scenario.']].map(([v,l,s])=>`<label class="decision-option"><input type="radio" name="outcome" value="${v}"${draft.outcome===v?' checked':''}><span>${l}<small>${s}</small></span></label>`).join('')}</fieldset>${draft.outcome==='close'?state.evidence?'<div class="notice success">Hypothetical invoices and a supplier schedule are loaded. Explain why those example documents support closure.</div>':'<div class="notice warning"><strong>Closure is currently blocked.</strong><br>The purpose of these transfers is unverified. To explore the closure scenario, load the example evidence below.</div>':''}<label class="form-label" for="rationale">Decision rationale <span class="small">(required)</span></label><textarea id="rationale" name="rationale" maxlength="3000" aria-describedby="rationale-hint" placeholder="What did you observe, what is still unknown and why is this the appropriate next step?">${esc(draft.rationale)}</textarea><p id="rationale-hint" class="form-hint">At least 30 characters. Keep the rationale consistent with your selected next step. Use synthetic information only.</p><button type="button" class="quiet" id="example-rationale">Use an example rationale</button>${draft.outcome==='request'?`<div class="form-fields"><div><label class="form-label" for="request-item">Information to request (required)</label><input type="text" id="request-item" maxlength="500" value="${esc(draft.requestItem)}" placeholder="e.g. invoices and supplier payment schedule"></div><div><label class="form-label" for="request-owner">Responsible reviewer (required)</label><input type="text" id="request-owner" maxlength="100" value="${esc(draft.owner)}"></div><div><label class="form-label" for="request-due">Follow-up due date (required)</label><input type="date" id="request-due" min="2026-11-14" value="${esc(draft.dueDate)}"><p class="form-hint">Scenario review date: 14 Nov 2026. No request will be sent.</p></div></div>`:''}<div id="form-errors"${errors.length?' class="validation" role="alert" tabindex="-1"':' hidden'}>${errors.map(e=>`<div>${esc(e)}</div>`).join('')}</div><div class="button-row"><button class="button primary" type="submit">Save decision</button><button class="button secondary" type="button" id="cancel-decision">Back to overview</button></div></form></section><aside><section class="panel"><h3>Evidence checkpoint</h3><p>Incoming: <strong>CAD 19,600</strong><br>Outgoing: <strong>CAD 17,800</strong><br>Last inflow → outflows: <strong>44 / 79 min</strong></p>${evidencePanel()}${!state.evidence?'<button class="button secondary" id="load-evidence">Load example supporting evidence</button><p class="small">Changes the scenario: assume matched invoices and a supplier schedule have been verified. These documents are fictional and are not attached.</p>':'<p class="small">This closure variant is hypothetical. Reset the demo to return to unverified transfer purpose.</p>'}</section><section class="panel"><h3>Decision history</h3><p>${state.records.length} ${state.records.length===1?'decision':'decisions'} saved in this browser.</p><button class="quiet" id="see-history">View the decision log →</button></section></aside></div>`;
  $('#rationale').oninput=e=>draft.rationale=e.target.value;
  document.querySelectorAll('[name=outcome]').forEach(r=>r.onchange=()=>{draft.outcome=r.value;renderDecision();document.querySelector(`[name=outcome][value=${draft.outcome}]`).focus({preventScroll:true});});
  $('#request-item')?.addEventListener('input',e=>draft.requestItem=e.target.value);$('#request-owner')?.addEventListener('input',e=>draft.owner=e.target.value);$('#request-due')?.addEventListener('input',e=>draft.dueDate=e.target.value);
  $('#example-rationale').onclick=()=>{draft.rationale={escalate:'Escalate for deeper review: CAD 19,600 arrived from eight counterparties and CAD 17,800 left 44 and 79 minutes after the final inflow. Transfer purpose and supporting invoices remain unverified.',request:'Request invoices for the incoming transfers and a supplier payment schedule for the two outgoing transfers. The rapid movement merits clarification, but the current pattern does not establish wrongdoing.',close:'In this hypothetical evidence scenario, matched invoices explain the incoming transfers and a verified supplier schedule explains both outgoing payments. Close this example alert with the supporting context recorded.'}[draft.outcome];if(draft.outcome==='request')draft.requestItem='Invoices for 14 incoming transfers and the supplier payment schedule for TX-2015 and TX-2016.';if(state.evidence&&draft.outcome==='escalate')draft.rationale='The hypothetical invoices and supplier schedule explain the transfer purpose, but counterparty relationships still need a deeper review. Escalate to verify the wider context before concluding the review.';if(state.evidence&&draft.outcome==='request'){draft.rationale='The hypothetical invoices and supplier schedule are available. Request clarification of counterparty relationships and the wider business context before deciding whether further investigation is needed.';draft.requestItem='Clarification of the customer’s relationship to incoming and outgoing counterparties.';}renderDecision();$('#rationale').focus({preventScroll:true});};
  $('#load-evidence')?.addEventListener('click',()=>{state={...state,evidence:true};persist();renderDecision();toast('Hypothetical supporting evidence loaded. The initial scenario has changed.');});
  $('#cancel-decision').onclick=()=>{tab='overview';renderCase();};$('#see-history').onclick=()=>show('history');
  $('#decision-form').onsubmit=e=>{e.preventDefault();if(state.records.length>=200){renderDecision(['This demo has reached its 200-decision limit. Export the log, then reset to continue.']);return;}const result=addDecision(state,draft);if(result.errors){renderDecision(result.errors);$('#form-errors').focus({preventScroll:true});return;}state=result.state;persist();draft=newDraft();saved=true;tab='overview';renderCase();app.focus({preventScroll:true});toast(`Decision saved: ${STATUS[result.record.outcome]}.`);};
}
function recordMarkup(r){return `<article class="decision-record"><h3>${esc(r.id)} ${badge(STATUS[r.outcome])}</h3><div class="record-meta"><span>${esc(timestamp(r.at))}</span><span>${esc(r.reviewer)}</span></div><p>${esc(r.rationale)}</p>${r.outcome==='request'?`<p><strong>Requested:</strong> ${esc(r.requestItem)}<br><strong>Responsible reviewer:</strong> ${esc(r.owner)}<br><strong>Follow-up:</strong> ${esc(r.dueDate)}</p>`:''}<p class="small">Evidence at decision: ${r.evidence?'hypothetical matched invoices and supplier schedule loaded':'transfer purpose and documents unverified'}.</p></article>`;}
function renderHistory(){
  app.innerHTML=`<div class="app-heading"><div><p class="eyebrow">ALT-1042 / LOCAL RECORD</p><h2>Decision log</h2><p>Reasoning stays attached to each next step.</p></div>${state.records.length?'<button id="export-log" class="button secondary">Export JSON ↓</button>':''}</div><div class="notice">This is a browser-local demonstration, not a bank audit trail. Records can be reset or changed through browser tools. No real case, escalation or information request is created.</div><section class="panel">${state.records.length?[...state.records].reverse().map(recordMarkup).join(''):'<div class="empty-state"><h3>No decisions recorded yet</h3><p>Review ALT-1042 and save a reasoned next step to create a local record.</p></div>'}</section><div class="button-row"><button id="history-open" class="button primary">Review ALT-1042 →</button><button id="history-queue" class="button secondary">Back to queue</button></div>`;
  $('#export-log')?.addEventListener('click',()=>download('signal-demo-decision-log.json',JSON.stringify({project:'Signal',synthetic:true,exportedAt:new Date().toISOString(),warning:'Browser-local demo records, not an operational audit trail',...state},null,2),'application/json'));
  $('#history-open').onclick=()=>{tab='overview';show('case');};$('#history-queue').onclick=()=>show('queue');
}
function toCSV(rows){const fields=['id','date','time','direction','counterparty','amount','currency','channel','customer','synthetic'];return fields.join(',')+'\r\n'+rows.map(t=>fields.map(f=>'"'+String(f==='synthetic'?'True':t[f]).replaceAll('"','""')+'"').join(',')).join('\r\n');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared.');}
$('#reset-demo').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{state=emptyState();persist();draft=newDraft();queueSearch='';queueFilter='All';direction='All';txSearch='';keyOnly=false;tab='overview';$('#reset-dialog').close();show('queue');toast('Demo reset. ALT-1042 is New again.');};
render();

for(const link of document.querySelectorAll('a[href="#model-note"]'))link.addEventListener('click',()=>document.querySelector('#model-note').open=true);
